    Store.data.lessons[lessonId].page = cur; Store.save();
    if (isSummary) { $$('[data-p]', root).forEach(b => b.onclick = () => UI.go('problem', { pid: b.dataset.p, lessonId })); $('#startProbs').onclick = () => { const first = probs.find(p => Store.prob(p.id).status !== 'clear') || probs[0]; UI.go('problem', { pid: first.id, lessonId }); }; const sd = $('#startDrills'); if (sd) sd.onclick = () => Sessions.drill(lessonId); return; }
    let lpFig = null; if (typeof Fig !== 'undefined' && $('#lpFig')) { const fpg = pg.figure ? pg : { ...pg, figure: { ...pages[0].figure, height: 200 }, observe: null }; /* 식·코드 페이지도 같은 그림을 작게 — 슬라이더 ↔ 코드 동기화 */ lpFig = MathUI.lessonFigure($('#lpFig'), l, fpg, () => exampleEditor); root._lpFig = lpFig; if (cur === 0 && !(Store.data.lessons[lessonId].figSeen)) { Store.data.lessons[lessonId].figSeen = 1; } }
