        let runCode = code; const sl = pg.example.slider && $('#exSl'); if (sl) { const re = new RegExp('^(\\s*)' + pg.example.slider.var + '\\s*=.*$', 'm'); runCode = re.test(code) ? code.replace(re, '$1' + pg.example.slider.var + ' = ' + sl.value) : pg.example.slider.var + ' = ' + sl.value + '\n' + code; }
        const r = await Py.run({ code: runCode, input: $('#exIn') ? $('#exIn').value : '', trace, onOut: (t, e) => { out.textContent += t; if (e) out.classList.add('haserr'); } });
        if (sl && r.ok && r.ms != null) { const tl = $('#exTimes'); if (tl) { const hist = (tl._h = tl._h || []); hist.push({ n: +sl.value, ms: r.ms }); const mx = Math.max(...hist.map(h => h.ms), 1); tl.innerHTML = hist.slice(-8).map(h => `<div class="ex-t"><span class="ex-tn">${h.n}</span><div class="ex-tb" style="width:${Math.max(4, Math.round(h.ms / mx * 100))}%"></div><span class="ex-tm">${h.ms < 1 ? '<1' : Math.round(h.ms)}ms</span></div>`).join(''); } }
        if (trace && r.trace) { TracePanel.show($('#exTracePanel'), r, exampleEditor); if (r.out != null) out.textContent = r.out; }
        if (!r.ok) { out.innerHTML += `<div class="errbox"><b>${esc(r.ename)}</b>: ${esc(r.emsg || '')}<br><span class="errko">💡 ${esc(Py.explain(r))}${r.ename === 'SyntaxError' ? ' ' + esc(Py.syntaxTips(code, r.line)) : ''}</span> <button class="btn xs" id="exErrMore">자세히</button></div>`; if (r.line) exampleEditor.setErrorLine(r.line); Game.recordError(null); const b = $('#exErrMore'); if (b) b.onclick = () => UI.go('errors', { name: r.ename }); Game.checkBadges().forEach(bd => UI.badgeFly(bd)); }
